package com.smartstock;
import java.io.*;import java.util.*;import java.util.zip.*;import java.math.*;import javax.xml.parsers.*;import javax.xml.transform.*;import javax.xml.transform.dom.*;import javax.xml.transform.stream.*;import org.w3c.dom.*;
public class Book {
 static final String NS="http://schemas.openxmlformats.org/spreadsheetml/2006/main";
 final Map<String,byte[]> entries=new LinkedHashMap<>(); final List<Item> items=new ArrayList<>(); final Map<String,List<Item>> index=new HashMap<>(); Document sheet; String path; String[] cols=new String[8]; int header;
 public static class Item { public String[] data=new String[7]; public BigDecimal cost; public BigInteger qty=BigInteger.ZERO; public boolean counted; int row; public BigDecimal total(){return cost.multiply(new BigDecimal(qty));} }
 static Document parse(byte[] b)throws Exception {DocumentBuilderFactory f=DocumentBuilderFactory.newInstance();f.setNamespaceAware(true);f.setFeature("http://apache.org/xml/features/disallow-doctype-decl",true);return f.newDocumentBuilder().parse(new ByteArrayInputStream(b));}
 static List<Element> nodes(Node n,String tag){NodeList l=n instanceof Document?((Document)n).getElementsByTagNameNS("*",tag):((Element)n).getElementsByTagNameNS("*",tag);List<Element> a=new ArrayList<>();for(int i=0;i<l.getLength();i++)a.add((Element)l.item(i));return a;}
 static String val(Element e,String tag){List<Element> a=nodes(e,tag);return a.isEmpty()?"":a.get(0).getTextContent();}
 static String norm(String s){return s.trim().replace('_',' ').replace('أ','ا').replace('إ','ا').replaceAll("\\s+"," ");}
 static String col(Element c){return c.getAttribute("r").replaceAll("[0-9]","");}
 static String text(Element c,List<String> ss){String t=c.getAttribute("t"),v=val(c,"v");if(t.equals("s"))return ss.get(Integer.parseInt(v));if(t.equals("inlineStr")){StringBuilder b=new StringBuilder();for(Element x:nodes(c,"t"))b.append(x.getTextContent());return b.toString();}if(t.equals("e"))throw new IllegalArgumentException("خلية خطأ: "+c.getAttribute("r"));return v;}
 public Book(InputStream input)throws Exception {try(ZipInputStream z=new ZipInputStream(input)){ZipEntry e;long size=0;while((e=z.getNextEntry())!=null){ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] buf=new byte[8192];int n;while((n=z.read(buf))>0){size+=n;if(size>150_000_000)throw new IOException("ملف كبير جداً");b.write(buf,0,n);}entries.put(e.getName(),b.toByteArray());}}
 Document wb=parse(entries.get("xl/workbook.xml"));List<Element> sheets=nodes(wb,"sheet");Element chosen=null;for(Element e:sheets)if(norm(e.getAttribute("name")).equals("تصدير بلاس"))chosen=e;if(chosen==null&&sheets.size()==1)chosen=sheets.get(0);if(chosen==null)throw new IOException("اختر ملف تصدير بلاس");String id=chosen.getAttributeNS("http://schemas.openxmlformats.org/officeDocument/2006/relationships","id");for(Element e:nodes(parse(entries.get("xl/_rels/workbook.xml.rels")),"Relationship"))if(e.getAttribute("Id").equals(id)){String t=e.getAttribute("Target");path=t.startsWith("/")?t.substring(1):"xl/"+t;}sheet=parse(entries.get(path));List<String> ss=new ArrayList<>();if(entries.containsKey("xl/sharedStrings.xml"))for(Element e:nodes(parse(entries.get("xl/sharedStrings.xml")),"si")){StringBuilder b=new StringBuilder();for(Element x:nodes(e,"t"))b.append(x.getTextContent());ss.add(b.toString());}
 String[][] names={{"اسم المجموعة"},{"اسم الصنف"},{"الوحدة"},{"العبوة","العبوة / حبة","العبوة/حبة"},{"الباركود"},{"الكمية"},{"التكلفة"},{"اجمالي التكلفة","اجمالي تكلفة الصف","اجمالي التكلفة للصف","الاجمالي"}};
 List<Element> rows=nodes(sheet,"row");for(Element r:rows){if(header==0){for(Element c:nodes(r,"c")){String v=norm(text(c,ss));for(int i=0;i<8;i++)for(String name:names[i])if(v.equals(name))cols[i]=col(c);}for(int i=0;i<7;i++)if(cols[i]==null)throw new IOException("عمود مفقود: "+names[i][0]);header=Integer.parseInt(r.getAttribute("r"));if(cols[7]==null){int max=0;for(Element cell:nodes(sheet,"c")){int k=0;for(char ch:col(cell).toCharArray())k=k*26+ch-'A'+1;max=Math.max(max,k);}cols[7]=letters(max+1);put(r,cols[7],"إجمالي التكلفة",true);}continue;}
 Item p=new Item();p.row=Integer.parseInt(r.getAttribute("r"));Arrays.fill(p.data,"");for(Element c:nodes(r,"c"))for(int i=0;i<7;i++)if(col(c).equals(cols[i]))p.data[i]=text(c,ss).trim();if(p.data[1].isEmpty()&&p.data[4].isEmpty())continue;if(p.data[1].isEmpty())throw new IOException("اسم مفقود في صف "+p.row);try{p.cost=new BigDecimal(p.data[6]);if(p.cost.signum()<0)throw new Exception();if(!p.data[5].isEmpty()&&new BigDecimal(p.data[5]).signum()!=0)throw new Exception();}catch(Exception ex){throw new IOException("تكلفة غير صالحة أو كمية افتتاحية غير صفرية: صف "+p.row);}items.add(p);if(!p.data[4].isEmpty())index.computeIfAbsent(p.data[4],k->new ArrayList<>()).add(p);}
 if(items.isEmpty())throw new IOException("لا توجد أصناف جاهزة للجرد"); }
 static String letters(int n){String s="";while(n>0){n--;s=(char)('A'+n%26)+s;n/=26;}return s;}
 void put(Element row,String col,String value,boolean string){String ref=col+row.getAttribute("r");Element c=null;for(Element e:nodes(row,"c"))if(e.getAttribute("r").equals(ref))c=e;if(c==null){c=sheet.createElementNS(NS,"c");c.setAttribute("r",ref);row.appendChild(c);}while(c.hasChildNodes())c.removeChild(c.getFirstChild());c.removeAttribute("t");if(string){c.setAttribute("t","inlineStr");Element is=sheet.createElementNS(NS,"is"),t=sheet.createElementNS(NS,"t");t.setTextContent(value);is.appendChild(t);c.appendChild(is);}else{Element v=sheet.createElementNS(NS,"v");v.setTextContent(value);c.appendChild(v);}}
 public void export(OutputStream out)throws Exception {Map<Integer,Item> m=new HashMap<>();for(Item p:items)m.put(p.row,p);for(Element r:nodes(sheet,"row")){Item p=m.get(Integer.parseInt(r.getAttribute("r")));if(p!=null){put(r,cols[5],p.qty.toString(),false);put(r,cols[7],p.total().toPlainString(),false);}}ByteArrayOutputStream b=new ByteArrayOutputStream();TransformerFactory.newInstance().newTransformer().transform(new DOMSource(sheet),new StreamResult(b));try(ZipOutputStream z=new ZipOutputStream(out)){for(Map.Entry<String,byte[]> e:entries.entrySet()){z.putNextEntry(new ZipEntry(e.getKey()));z.write(e.getKey().equals(path)?b.toByteArray():e.getValue());z.closeEntry();}}}
}
